CREATE DATABASE IF NOT EXISTS FLEET_APP COMMENT='{"origin":"sf_sit-is-fleet","name":"build-routing-solution","attributes":{"component":"data-contract-app-layer"}}';
CREATE SCHEMA IF NOT EXISTS FLEET_APP.TAXI COMMENT='Stable logical layer for the taxi pack (generated from data-model + entity-mapping).';

CREATE OR REPLACE VIEW FLEET_APP.TAXI.VW_TRIPS AS
SELECT
    VEHICLE_ID, TRIP_ID, TRIP_START, TRIP_END,
    ORIGIN_POI_ID, DESTINATION_POI_ID,
    DURATION_MINUTES, DISTANCE_KM, ROUTE_GEOG, ORIGIN, DESTINATION, REGION
FROM SYNTHETIC_DATASETS.UNIFIED.FACT_TRIPS
WHERE VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_TAXIS.CONFIG LIMIT 1)
  AND REGION = (SELECT REGION FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_TAXIS.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.TAXI.VW_TELEMETRY AS
SELECT TRIP_ID, SPEED_KMH
FROM SYNTHETIC_DATASETS.UNIFIED.FACT_VEHICLE_TELEMETRY
WHERE VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_TAXIS.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.TAXI.VW_POIS AS
SELECT LOCATION_ID, NAME, CATEGORY, LAT, LNG
FROM SYNTHETIC_DATASETS.UNIFIED.DIM_POIS;

CREATE OR REPLACE VIEW FLEET_APP.TAXI.VW_FLEET AS
SELECT VEHICLE_ID, SHIFT_TYPE
FROM SYNTHETIC_DATASETS.UNIFIED.DIM_FLEET
WHERE VEHICLE_TYPE = (SELECT VEHICLE_TYPE FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_TAXIS.CONFIG LIMIT 1);

CREATE OR REPLACE VIEW FLEET_APP.TAXI.VW_CONFIG AS
SELECT * FROM FLEET_INTELLIGENCE.FLEET_INTELLIGENCE_TAXIS.CONFIG;

CREATE OR REPLACE VIEW FLEET_APP.TAXI.VW_TRIP_SUMMARY AS
WITH trip_speeds AS (
    SELECT TRIP_ID, MAX(SPEED_KMH) AS MAX_KMH
    FROM FLEET_APP.TAXI.VW_TELEMETRY
    GROUP BY TRIP_ID
),
dedup_pois AS (
    SELECT LOCATION_ID, NAME, CATEGORY, LAT, LNG,
           ROW_NUMBER() OVER (PARTITION BY LOCATION_ID ORDER BY NAME) AS RN
    FROM FLEET_APP.TAXI.VW_POIS
),
dedup_fleet AS (
    SELECT VEHICLE_ID, SHIFT_TYPE,
           ROW_NUMBER() OVER (PARTITION BY VEHICLE_ID ORDER BY SHIFT_TYPE) AS RN
    FROM FLEET_APP.TAXI.VW_FLEET
)
SELECT
    t.VEHICLE_ID AS DRIVER_ID,
    t.TRIP_ID,
    t.TRIP_START AS TRIP_START_TIME,
    t.TRIP_END AS TRIP_END_TIME,
    COALESCE(po.NAME, 'Unknown') AS ORIGIN_ADDRESS,
    COALESCE(pd.NAME, 'Unknown') AS DESTINATION_ADDRESS,
    t.DURATION_MINUTES * 60 AS ROUTE_DURATION_SECS,
    t.DISTANCE_KM * 1000 AS ROUTE_DISTANCE_METERS,
    t.ROUTE_GEOG AS GEOMETRY,
    t.ORIGIN,
    t.DESTINATION,
    CASE f.SHIFT_TYPE
        WHEN '6-14' THEN 'Morning'
        WHEN '14-22' THEN 'Afternoon'
        WHEN '22-6' THEN 'Night'
        ELSE f.SHIFT_TYPE
    END AS SHIFT_TYPE,
    t.REGION,
    CASE WHEN t.DURATION_MINUTES > 0
         THEN t.DISTANCE_KM / (t.DURATION_MINUTES / 60)
         ELSE 0 END AS AVERAGE_KMH,
    ts.MAX_KMH
FROM FLEET_APP.TAXI.VW_TRIPS t
LEFT JOIN dedup_pois po ON t.ORIGIN_POI_ID = po.LOCATION_ID AND po.RN = 1
LEFT JOIN dedup_pois pd ON t.DESTINATION_POI_ID = pd.LOCATION_ID AND pd.RN = 1
LEFT JOIN dedup_fleet f ON t.VEHICLE_ID = f.VEHICLE_ID AND f.RN = 1
LEFT JOIN trip_speeds ts ON t.TRIP_ID = ts.TRIP_ID;

